import clsx from 'clsx'
import type { PropsWithChildren, ReactNode } from 'react'
import React from 'react'
import type { AllColors } from '../utilities/colors'

export interface AvatarProps {
  /**
   * Accessible label for the avatar.
   * If not provided, the `name` prop is be used
   */
  'aria-label'?: string
  /**
   * The content to display as initials in the avatar. If a string is given, it will extract up to 2 capital letters or first letters of words. Otherwise, the provided content will be rendered as is
   */
  children?: ReactNode
  /**
   * The color scheme of the avatar background and text
   * @default 'default'
   */
  color?: AvatarColor
  /**
   * The name to display as initials in the avatar.
   * Will extract up to 2 capital letters or first letters of words
   */
  name?: string
  /**
   * The shape variant of the avatar
   * @default 'circle'
   */
  variant?: AvatarVariant

  /**
   * The size of the avatar
   * @default 'medium'
   */
  size?: AvatarSize
}

export type AvatarColor = AllColors | 'green'
type AvatarColors = { [key in AllColors | 'green']: string }

type AvatarVariant = 'circle' | 'rounded' | 'square'
type AvatarSize = 'small' | 'medium' | 'large' | 'xlarge'

type AvatarVariants = {
  [key in AvatarVariant]: string
}

type AvatarSizes = {
  [key in AvatarSize]: string
}

// TODO: Make shared values for these utility colors
export const colors: AvatarColors = {
  // --- Legacy / Backwards Compatibility Colors ---
  default: 'bg-zinc-100 text-zinc-800 border-zinc-200',
  primary: 'bg-primary-10 text-primary-darker border-primary-20',
  secondary: 'bg-secondary-10 text-secondary-darker border-secondary-20',
  blue: 'bg-sky-100 text-sky-800 border-sky-200',
  error: 'bg-red-100 text-red-800 border-red-200',
  green: 'bg-lime-100 text-lime-800 border-lime-200',
  indigo: 'bg-violet-100 text-violet-700 border-violet-200',
  pink: 'bg-pink-100 text-pink-700 border-pink-200',
  purple: 'bg-fuchsia-100 text-fuchsia-700 border-fuchsia-200',
  red: 'bg-rose-100 text-rose-700 border-rose-200',
  teal: 'bg-teal-100 text-teal-800 border-teal-200',
  warning: 'bg-yellow-100 text-yellow-800 border-yellow-200',
  yellow: 'bg-amber-100 text-amber-800 border-amber-200',

  // --- New Semantic Color Tokens ---
  grey: 'bg-gray-200 text-gray-800 border-gray-300',
  info: 'bg-info-50 text-info-800 border-info-300',
  success: 'bg-success-50 text-success-800 border-success-300',
  neutral: 'bg-neutral-50 text-neutral-800 border-neutral-300',
  muted: 'bg-muted-50 text-muted-800 border-muted-300',
  intelligence:
    'bg-intelligence-50 text-intelligence-800 border-intelligence-300',
}

const sizes: AvatarSizes = {
  small: 'text-sm w-6 h-6 p-1',
  medium: 'text-xl w-10 h-10 p-2',
  large: 'text-3xl w-16 h-16 p-2',
  xlarge: 'text-4xl w-20 h-20 p-2',
}

const variants: AvatarVariants = {
  circle: 'rounded-full',
  square: '',
  rounded: 'rounded-md',
}

function Avatar({
  'aria-label': label,
  children,
  color = 'default',
  name,
  variant = 'circle',
  size = 'medium',
}: PropsWithChildren<AvatarProps>): JSX.Element {
  return (
    <div
      aria-label={label || name}
      className={clsx(
        'justify-center items-center inline-flex shrink-0 border',
        colors[color],
        sizes[size],
        variants[variant],
      )}
      role="img"
    >
      {name !== undefined
        ? name.match(/[A-Z]/g)?.slice(0, 2)?.join('') ||
          name
            .split(' ')
            .slice(0, 2)
            .map((word) => word.substring(0, 1).toUpperCase())
            .join('')
        : typeof children === 'string'
        ? children.substring(0, 2).toUpperCase()
        : children}
    </div>
  )
}

export default Avatar
